import createCache from '@emotion/cache';
 import { CacheProvider } from '@emotion/react';
 import { createRoot, type Root } from 'react-dom/client';
 import { App } from './app';
 import type { MFEModule, MFEMeta } from '@fsd/mfe-shell';

 export const meta: MFEMeta = {
 name: 'copywala',
 version: '1.0.0',
 apiVersion: 1,
 };

 const roots = new WeakMap<HTMLElement | ShadowRoot, Root>();

 export const mount: MFEModule['mount'] = (root, ctx) => {
 let reactRoot = roots.get(root);
 if (!reactRoot) {
 reactRoot = createRoot(root as Element);
 roots.set(root, reactRoot);
 }
 const cache = createCache({
 key: 'cw',
 container: root as unknown as Node,
 prepend: true,
 });
 reactRoot.render(
 <CacheProvider value={cache}>
 <App />
 </CacheProvider>,
 );
 const unmount = () => {
 const r = roots.get(root);
 if (!r) return;
 r.unmount();
 roots.delete(root);
 };
 ctx.signal.addEventListener('abort', unmount, { once: true });
 return unmount;
 };

 export default App;
Скрипт сборки микросервисов
Код:
import { execSync } from "child_process";
 import { cpSync, mkdirSync, writeFileSync, existsSync, rmSync, readFileSync, readdirSync, statSync } from "fs";
 import * as path from "path";

 const SERVICES = ["logDashboard"];
 const HOST_PUBLIC = path.resolve("..", "host/public");
 const MICRO_DIR = path.resolve("..", "microservices");
 const MANIFEST_INPUT_PATH = path.resolve(HOST_PUBLIC, "manifest.json");

 if (existsSync(MICRO_DIR)) rmSync(MICRO_DIR, { recursive: true });
 let manifest = { version: "1.0.0", services: [] };

 if (existsSync(MANIFEST_INPUT_PATH)) {
 try {
 const rawData = readFileSync(MANIFEST_INPUT_PATH);
 const parsedData = JSON.parse(rawData);
 manifest = { ...parsedData, services: [] };
 } catch (error) {
 console.warn("Ошибка парсинга manifest.json. Используется шаблон по умолчанию:", error.message);
 }
 }

 for (const name of SERVICES) {
 try {
 execSync(cd ${name} && rm -rf node_modules && npm i --legacy-peer-deps && npm run build:mfe, { stdio: "inherit" });
 const srcBuildDir = path.resolve(${name}/build-mfe);
 const dest = path.resolve(MICRO_DIR);
 mkdirSync(dest, { recursive: true });
 const esFiles = readdirSync(srcBuildDir).filter((f) => f.endsWith(".js"));
 for (const fileName of esFiles) {
 const srcFile = path.resolve(srcBuildDir, fileName);
 const destFile = path.resolve(${dest}/${name}/, fileName);
 if (statSync(srcFile).isFile()) {
 cpSync(srcFile, destFile);
 }
 manifest.services.push({ name, entry: /microservices/${name}/${fileName}, status: "active" });
 }
 } catch (e) {
 console.error(Ошибка сборки ${name}:, e.message);
 process.exit(1);
 }
 }

 writeFileSync(path.resolve(HOST_PUBLIC, "manifest.json"), JSON.stringify(manifest, null, 2));
Скрипт выполняет следующее: запускает сборку сервисов из конфига SERVICES (временная константа, пока нет файла конфигурации от пайплайна). Удаляет информацию о ранее смонтированных сервисах в хостовом манифесте, собирает микросервис и при успехе копирует
chunk
в папку микросервисов, прописывая путь до него в манифесте.
