function microservicesCopyPlugin(): Plugin {
 const microservicesSrc = path.resolve(__dirname, '../apps/microservices');
 let buildOutDir: string;
 return {
 name: 'microservices-copy-plugin',
 apply: 'build',
 configResolved(config) {
 buildOutDir = config.build.outDir;
 },
 closeBundle() {
 if (!existsSync(microservicesSrc)) return;
 const microservicesDest = path.resolve(buildOutDir, 'microservices');
 mkdirSync(microservicesDest, { recursive: true });
 const serviceDirs = readdirSync(microservicesSrc);
 for (const dirName of serviceDirs) {
 const fileNames = readdirSync(${microservicesSrc}/${dirName});
 for (const fileName of fileNames) {
 if (fileName.endsWith('.js')) {
 const srcFile = path.resolve(${microservicesSrc}/${dirName}, fileName);
 const destFile = path.resolve(${microservicesDest}/${dirName}, fileName);
 if (statSync(srcFile).isFile()) {
 cpSync(srcFile, destFile);
 }
 }
 }
 }
 },
 };
 }
